final class Fixtures
{
    /** @return array<string, string> */
    public static function all(): array
    {
        static $decoded = null;
        if ($decoded === null) {
            $decoded = [];
            foreach ((new ReflectionClass(FixtureText::class))->getConstants() as $name => $text) {
                $decoded[$name] = base64_decode($text, true);
            }
        }

        return $decoded;
    }

    public static function get(string $name): string
    {
        return self::all()[$name];
    }
}
